package kotobaya.sync

import java.io.File
import kotlin.test.Test
import kotlin.test.fail

/**
 * Keeps the generated embeddings of `contracts/sync` identical to the files (jvm only: common code
 * cannot read files).
 * - `commonMain/.../sync/SyncSchemaTexts.kt`: the canonical compact JSON of every schema
 *   (`common`, `op`, `batch`, `ops/<op_type>`), used by [SyncSchemas] on every platform.
 * - `commonTest/.../sync/SyncExamples.kt`: the verbatim texts of `examples/{ops,invalid,invalid-codec,batches,raw-push}`.
 *
 * On drift this writes the regenerated file under `core/build/sync-drift/` and fails; copy it over
 * the checked-in one and commit. Never hand-edit the generated files.
 */
class SyncContractDriftTest {
    private val root = File("../contracts/sync")
    private val out = File("build/sync-drift")

    @Test
    fun embeddedSchemasMatchContracts() {
        val opSchemas = root.resolve("ops").listFiles()!!.map { it.name }.filter { it.endsWith(".schema.json") }.sorted()
        val files = listOf("common.schema.json", "op.schema.json", "batch.schema.json") + opSchemas.map { "ops/$it" }
        val entries = files.joinToString("") { name ->
            val decoded = DefaultCanonicalJson.decode(root.resolve(name).readText())
            val canonical = DefaultCanonicalJson.encode(decoded.value ?: fail("$name: ${decoded.error}"))
            "        \"$name\" to\n            \"${kotlinEscape(canonical)}\",\n"
        }
        val source = "package kotobaya.sync\n\n" +
            "/**\n" +
            " * GENERATED by the jvm test `SyncContractDriftTest` from `contracts/sync/{common,op,batch}.schema.json`\n" +
            " * and `contracts/sync/ops/<op_type>.schema.json` (canonical compact JSON); do not edit.\n" +
            " */\n" +
            "internal object SyncSchemaTexts {\n" +
            "    /** Path relative to `contracts/sync` to the schema text. */\n" +
            "    val FILES: Map<String, String> = mapOf(\n" +
            entries +
            "    )\n" +
            "}\n"
        compare(File("src/commonMain/kotlin/kotobaya/sync/SyncSchemaTexts.kt"), source)
    }

    @Test
    fun embeddedExamplesMatchContracts() {
        fun group(doc: String, prop: String, dir: String, suffix: String): String {
            val names = root.resolve(dir).listFiles()!!.map { it.name }.filter { it.endsWith(suffix) }.sorted()
            val entries = names.joinToString("") { name ->
                "        \"$name\" to\n            \"${kotlinEscape(root.resolve("$dir/$name").readText())}\",\n"
            }
            return "    /** $doc */\n    val $prop: Map<String, String> = mapOf(\n$entries    )\n"
        }
        val source = "package kotobaya.sync\n\n" +
            "/**\n" +
            " * GENERATED by the jvm test `SyncContractDriftTest` from `contracts/sync/examples/` (verbatim file\n" +
            " * texts, keyed by file name); do not edit.\n" +
            " */\n" +
            "internal object SyncExamples {\n" +
            group("`examples/ops/`.", "ops", "examples/ops", ".json") + "\n" +
            group("`examples/invalid/`.", "invalid", "examples/invalid", ".json") + "\n" +
            group("`examples/invalid-codec/` (schema-valid; an op-level rule of SYNC.md 2.1 rejects them).", "invalidCodec", "examples/invalid-codec", ".json") + "\n" +
            group("`examples/batches/`.", "batches", "examples/batches", ".json") + "\n" +
            group("`examples/raw-push/<name>.body.txt`.", "rawPushBodies", "examples/raw-push", ".body.txt") + "\n" +
            group("`examples/raw-push/<name>.expected.json`.", "rawPushExpected", "examples/raw-push", ".expected.json") +
            "}\n"
        compare(File("src/commonTest/kotlin/kotobaya/sync/SyncExamples.kt"), source)
    }

    private fun compare(target: File, expected: String) {
        if (target.exists() && target.readText() == expected) return
        out.mkdirs()
        val regenerated = out.resolve(target.name)
        regenerated.writeText(expected)
        fail("${target.path} drifted from contracts/sync: regenerated at ${regenerated.absolutePath}; copy it over and commit")
    }

    private fun kotlinEscape(s: String): String = buildString {
        for (c in s) {
            when (c) {
                '\\' -> append("\\\\")
                '"' -> append("\\\"")
                '$' -> append("\\$")
                '\n' -> append("\\n")
                '\r' -> append("\\r")
                '\t' -> append("\\t")
                // non-ASCII as \uXXXX: invisible code points (U+FEFF, U+00A0, U+3000) stay visible in review
                // and the JS build never re-encodes source text
                else -> if (c.code < 0x20 || c.code > 0x7e) append("\\u%04x".format(c.code)) else append(c)
            }
        }
    }
}
